finalReview.targetSource:
function bFinalRemediationTarget(mode,source,domain){
  if(mode==='security')return {mode:'security',id:source};
  if(mode==='trace')return {mode:'trace',id:source};
  if(mode==='exam')return {mode:'trace',id:B_FINAL_DOMAIN_REMEDIATION[domain]||'binary_search_b'};
  if(mode==='compound')return {mode:'compound',id:source};
  return {mode:'mock',id:null};
}

